mapper.update:
UPDATE train_runner_command
SET status = 'LEASED', lease_until = #{leasedUntil},
    attempt_count = attempt_count + 1, updated_at = #{now}
WHERE runner_id = #{runnerId} AND command_id = #{commandId}
  AND (status = 'QUEUED' OR (status = 'LEASED' AND lease_until < #{now}))

UPDATE train_runner_command
SET status = 'RUNNING', updated_at = #{now}
WHERE runner_id = #{runnerId} AND command_id = #{commandId}
  AND attempt_count = #{attempt} AND status = 'LEASED'
  AND lease_until = #{leaseUntil} AND lease_until >= #{now}

UPDATE train_runner_command
SET status = #{status}, result = #{result}, error_code = #{errorCode}, updated_at = #{now}
WHERE runner_id = #{runnerId} AND command_id = #{commandId}
  AND attempt_count = #{attempt} AND status = 'RUNNING'

UPDATE train_runner_command
SET status = 'REJECTED', result = #{result}, error_code = #{errorCode}, updated_at = #{now}
WHERE runner_id = #{runnerId} AND command_id = #{commandId}
  AND attempt_count = #{attempt} AND status = 'LEASED'
  AND lease_until = #{leaseUntil} AND lease_until >= #{now}

UPDATE train_runner_command
SET status = #{nextStatus}, updated_at = #{now}
WHERE runner_id = #{runnerId} AND command_id = #{commandId}
  AND attempt_count = #{attempt} AND status = #{expectedStatus}
